mapper.sql:
from sys_notice n

    and n.title ilike #{q.keywordLike} escape '\'
    and n.cat_cd = #{q.catCd}
    and n.use_yn = 'N'
    and n.use_yn = 'Y' and n.post_from > #{q.today}
    and n.use_yn = 'Y' and n.post_to is not null and n.post_to < #{q.today}

        and n.use_yn = 'Y' and n.post_from <= #{q.today} and (n.post_to is null or n.post_to >= #{q.today})

mapper.update:
update sys_notice
   set cat_cd = #{f.catCd}, title = #{f.title}, body = #{f.body}, pin_yn = #{f.pinYn},
       post_from = #{f.postFrom}, post_to = #{f.postTo}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where notice_id = #{noticeId} and row_ver = #{f.rowVer}
